using System.ComponentModel.DataAnnotations;

namespace sv_70f47d90b0d442b5b4ff259af875872b.Models;

public class AppointmentModel : IValidatableObject
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    public string? Doctor { get; set; }

    public DateOnly? AppointmentDate { get; set; }

    public string? TimeSlot { get; set; }

    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string? ReasonForVisit { get; set; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (AppointmentDate.HasValue && AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            yield return new ValidationResult(
                "Appointment date must be in the future.",
                [nameof(AppointmentDate)]);
        }
    }
}

namespace sv_70f47d90b0d442b5b4ff259af875872b.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly Dictionary<string, List<string>> SlotsByDoctor = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "11:30 AM", "2:30 PM", "4:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:30 AM", "1:30 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        var slots = SlotsByDoctor.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient and appointment data against server-side business rules.
    /// Returns a dictionary of field name → error messages. Empty means valid.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string? email, string? insuranceProvider, string? doctor, string? timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject patients with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(Models.AppointmentModel.Email)] = ["Account has outstanding balance."];
        }

        // Reject self-pay for doctors who don't accept it
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(Models.AppointmentModel.Doctor)] = ["Selected doctor does not accept self-pay patients."];
        }

        // Simulate race condition on a specific slot
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(Models.AppointmentModel.TimeSlot)] = ["This slot is no longer available."];
        }

        return Task.FromResult(errors);
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_70f47d90b0d442b5b4ff259af875872b.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_70f47d90b0d442b5b4ff259af875872b.Models
@using sv_70f47d90b0d442b5b4ff259af875872b.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h2>Step 1: Patient Information</h2>

    <div>
        <label>
            Patient Name:
            <InputText @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </label>
    </div>

    <div>
        <label>
            Email:
            <InputText @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </label>
    </div>

    <div>
        <label>
            Phone:
            <InputText @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </label>
    </div>

    <div>
        <label>
            Insurance Provider:
            <InputSelect @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </label>
    </div>

    @if (!showStep2)
    {
        <button type="button" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <h2>Step 2: Appointment Details</h2>

        <div>
            <label>
                Preferred Doctor:
                <InputSelect @bind-Value="Model.Doctor" @bind:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </label>
        </div>

        <div>
            <label>
                Date:
                <InputDate @bind-Value="Model.AppointmentDate" @bind:after="OnDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </label>
        </div>

        <div>
            <label>
                Time Slot:
                <InputSelect @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </label>
        </div>

        <div>
            <label>
                Reason for Visit:
                <InputTextArea @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </label>
        </div>

        <button type="button" @onclick="CheckAvailability" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>

        @if (isConfirmed)
        {
            <button type="submit">Confirm Appointment</button>
        }
    }

    @if (submitSuccess)
    {
        <p><strong>Appointment booked successfully!</strong></p>
    }
</EditForm>

@code {
    private EditContext editContext = default!;
    private AppointmentModel Model = new();
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isConfirmed;
    private bool submitSuccess;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        var isValid = editContext.Validate();
        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged()
    {
        availableSlots = [];
        Model.TimeSlot = null;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task OnDateChanged()
    {
        availableSlots = [];
        Model.TimeSlot = null;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        isConfirmed = false;

        if (!editContext.Validate())
            return;

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private async Task HandleSubmit()
    {
        // Final server-side validation before booking
        customValidator?.ClearErrors();
        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (errors.Count > 0)
        {
            customValidator!.DisplayErrors(errors);
            isConfirmed = false;
            return;
        }

        submitSuccess = true;
    }
}

