namespace sv_70f47d90b0d442b5b4ff259af875872b.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly Dictionary<string, List<string>> SlotsByDoctor = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "11:30 AM", "2:30 PM", "4:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:30 AM", "1:30 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        var slots = SlotsByDoctor.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient and appointment data against server-side business rules.
    /// Returns a dictionary of field name → error messages. Empty means valid.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string? email, string? insuranceProvider, string? doctor, string? timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject patients with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(Models.AppointmentModel.Email)] = ["Account has outstanding balance."];
        }

        // Reject self-pay for doctors who don't accept it
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(Models.AppointmentModel.Doctor)] = ["Selected doctor does not accept self-pay patients."];
        }

        // Simulate race condition on a specific slot
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(Models.AppointmentModel.TimeSlot)] = ["This slot is no longer available."];
        }

        return Task.FromResult(errors);
    }
}

