@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h2>Step 1: Patient Information</h2>

    <div>
        <label>
            Patient Name:
            <InputText @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </label>
    </div>

    <div>
        <label>
            Email:
            <InputText @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </label>
    </div>

    <div>
        <label>
            Phone:
            <InputText @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </label>
    </div>

    <div>
        <label>
            Insurance Provider:
            <InputSelect @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </label>
    </div>

    @if (!showStep2)
    {
        <button type="button" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <h2>Step 2: Appointment Details</h2>

        <div>
            <label>
                Preferred Doctor:
                <InputSelect @bind-Value="Model.Doctor" @bind:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </label>
        </div>

        <div>
            <label>
                Date:
                <InputDate @bind-Value="Model.AppointmentDate" @bind:after="OnDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </label>
        </div>

        <div>
            <label>
                Time Slot:
                <InputSelect @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </label>
        </div>

        <div>
            <label>
                Reason for Visit:
                <InputTextArea @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </label>
        </div>

        <button type="button" @onclick="CheckAvailability" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>

        @if (isConfirmed)
        {
            <button type="submit">Confirm Appointment</button>
        }
    }

    @if (submitSuccess)
    {
        <p><strong>Appointment booked successfully!</strong></p>
    }
</EditForm>

@code {
    private EditContext editContext = default!;
    private AppointmentModel Model = new();
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isConfirmed;
    private bool submitSuccess;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        var isValid = editContext.Validate();
        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged()
    {
        availableSlots = [];
        Model.TimeSlot = null;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task OnDateChanged()
    {
        availableSlots = [];
        Model.TimeSlot = null;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        isConfirmed = false;

        if (!editContext.Validate())
            return;

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private async Task HandleSubmit()
    {
        // Final server-side validation before booking
        customValidator?.ClearErrors();
        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (errors.Count > 0)
        {
            customValidator!.DisplayErrors(errors);
            isConfirmed = false;
            return;
        }

        submitSuccess = true;
    }
}

